// Generated by Faultline from a verified, minimized counterexample.
// Double-clicking "Place order" sends the request twice
// Attribution: deterministic: reproduces without any network perturbation
// This test asserts the CORRECT behaviour: it fails while the bug exists and passes once it is fixed.
import { test, expect } from '@playwright/test';
test.use({ serviceWorkers: 'block' });

const TARGET = process.env.FAULTLINE_TARGET ?? "http://127.0.0.1:60765/demo/checkout.html?mode=fixed";

test("faultline: Double-clicking \"Place order\" sends the request twice", async ({ page }) => {
  const origin = new URL(TARGET).origin;
  const requests: { method: string; path: string }[] = [];
  const pageErrors: string[] = [];
  const isApi = (req: any) => ['fetch', 'xhr'].includes(req.resourceType()) && new URL(req.url()).origin === origin;
  page.on('request', (req) => { if (isApi(req)) requests.push({ method: req.method(), path: new URL(req.url()).pathname }); });
  page.on('pageerror', (error) => pageErrors.push(String(error)));
  await page.goto(TARGET);
  await page.waitForTimeout(250);
  // Enter "Ada Lovelace" into "Full name"
  if (await page.getByTestId("full-name").evaluate(el => el instanceof HTMLInputElement && el.type === 'password')) throw new Error('Refusing to type into a password field');
  await page.getByTestId("full-name").fill("Ada Lovelace");
  await page.waitForTimeout(120); // human-like pacing, same as Faultline's executor
  // Enter "ada@example.com" into "Email"
  if (await page.getByTestId("email").evaluate(el => el instanceof HTMLInputElement && el.type === 'password')) throw new Error('Refusing to type into a password field');
  await page.getByTestId("email").fill("ada@example.com");
  await page.waitForTimeout(120); // human-like pacing, same as Faultline's executor
  // Double-click "Place order"
  await page.getByTestId("place-order").dblclick();
  await page.waitForTimeout(120); // human-like pacing, same as Faultline's executor
  await page.waitForTimeout(450);
  // Invariant: At most 1 POST * request(s) are sent
  expect(requests.filter((r) => r.method === "POST").length).toBeLessThanOrEqual(1);
});
